import type * as RAPIER from "@dimforge/rapier3d-compat";

/**
 * Физический мир: одна загрузка движка на всех, кто в нём находится.
 *
 * Живёт в среде по той же причине, по которой здесь живёт ветер: мир один, а
 * тел в нём много. Машина строит в нём кузов и колёса, игра — полотно дороги, и
 * оба обязаны попасть в **тот же** мир, иначе колёса поедут сквозь асфальт. Пока
 * загрузка движка сидела внутри физики машины, дорога получала его от машины,
 * то есть трасса зависела от автомобиля ради вещи, к автомобилю не относящейся.
 *
 * Почему Rapier вообще уместен при требовании воспроизводимости: у него тот
 * самый контроллер машины, что и в Bullet, с рессорами и лучами подвески, и он
 * оказался побитово детерминированным — два независимых мира с одинаковыми
 * входами дали одинаковые траектории до последнего знака. Цена — мегабайт WASM,
 * поэтому пакет подгружается динамически и только тогда, когда игре нужна
 * физика: стенду с деревьями она не нужна, и он её не платит.
 */

let api: typeof RAPIER | null = null;

/** Загрузка WASM. Игра без неё не шагает, поэтому её ждут до запуска. */
export async function preparePhysics(): Promise<void> {
  if (api) return;
  const mod = await import("@dimforge/rapier3d-compat");
  await mod.init();
  api = mod;
}

export function physicsReady(): boolean {
  return api !== null;
}

/** Движок для тех, кто строит тела: без загрузки — сразу и внятно падаем. */
export function rapier(): typeof RAPIER {
  if (!api) throw new Error("env: физика не загружена, нужен preparePhysics()");
  return api;
}

/**
 * Шаг интегрирования фиксирован: от него зависит и устойчивость, и повторяемость.
 * Он один на весь мир — и кузов, и дорога, и накопитель времени в игре считают
 * им же.
 */
export const PHYSICS_STEP_S = 1 / 60;

/** Мир с земным тяготением и общим шагом. */
export function createWorld(): RAPIER.World {
  const world = new (rapier().World)({ x: 0, y: -9.81, z: 0 });
  world.timestep = PHYSICS_STEP_S;
  return world;
}
